  $("#cafe_menu_nav a, .scrollLink").on('click', function (e) {
    var className = $(this).attr("href");

    if (className.charAt(0) === "#") {
      e.preventDefault();
      var hash = this.hash,
          scrollTopOffset = $(hash).offset().top;
      $('html, body').animate({
        scrollTop: scrollTopOffset
      }, 500);
    }
  });
  /** => End Smooth Scrolling */

